
.char-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 6px;
}

.info-item {
  display: flex;
  gap: 6px;
  padding: 6px 8px;
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
}

.info-label {
  color: var(--c-cyan);
  font-size: 0.72rem;
  white-space: nowrap;
}

.info-value {
  color: var(--c-text);
  font-size: 0.8rem;
  font-weight: bold;
}

.info-value.tier {
  color: var(--c-yellow);
}

.info-value.mod {
  color: var(--c-magenta);
}

.info-value.def {
  color: var(--c-green);
}

.section-title {
  color: var(--c-cyan);
  font-size: 0.75rem;
  font-weight: bold;
  padding: 4px 0;
  border-bottom: 1px solid var(--c-cyan);
  text-shadow: var(--glow-cyan);
}

.status-block {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.status-item {
  display: flex;
  gap: 8px;
  padding: 6px 10px;
  background: var(--c-bg-dark);
  border-left: 2px solid var(--c-border);
}

.status-item.highlight {
  border-left-color: var(--c-magenta);
  background: rgba(255, 0, 255, 0.05);
}

.status-label {
  color: var(--c-text-dim);
  font-size: 0.72rem;
  min-width: 45px;
}

.status-text {
  color: var(--c-text);
  font-size: 0.8rem;
}

.appearance-box {
  padding: 10px;
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
  color: var(--c-text-dim);
  font-size: 0.8rem;
  line-height: 1.5;
}
