
.header-section {
  background: var(--c-bg-dark);
  border-bottom: 1px solid var(--c-cyan);
  padding: 10px 12px;
}

.system-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  font-size: 0.85rem;
}

.sys-label {
  color: var(--c-cyan);
  text-shadow: var(--glow-cyan);
}

.sys-time {
  color: var(--c-text);
  font-weight: bold;
}

.sys-divider {
  color: var(--c-text-dim);
}

.sys-layer {
  padding: 2px 8px;
  font-size: 0.75rem;
  font-weight: bold;
  border: 1px solid;
}

.layer-upper {
  color: var(--c-magenta);
  border-color: var(--c-magenta);
  text-shadow: var(--glow-magenta);
}

.layer-middle {
  color: var(--c-cyan);
  border-color: var(--c-cyan);
  text-shadow: var(--glow-cyan);
}

.layer-lower {
  color: var(--c-yellow);
  border-color: var(--c-yellow);
}

.layer-outskirts {
  color: var(--c-red);
  border-color: var(--c-red);
  text-shadow: var(--glow-red);
}

.location-bar {
  display: flex;
  gap: 6px;
  font-size: 0.8rem;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--c-border);
}

.loc-prefix {
  color: var(--c-green);
}

.loc-text {
  color: var(--c-text);
}

.mission-list {
  background: rgba(0, 240, 255, 0.03);
  border: 1px solid var(--c-border);
  padding: 8px;
}

.mission-header {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--c-yellow);
  font-size: 0.75rem;
  margin-bottom: 6px;
  text-transform: uppercase;
}

.mission-icon {
  animation: neonPulse 1.5s ease-in-out infinite;
}

.mission-items {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.mission-item {
  display: flex;
  flex-direction: column;
  padding: 4px 8px;
  border-left: 2px solid var(--c-cyan);
  background: rgba(0, 0, 0, 0.3);
}

.mission-item.empty {
  border-left-color: var(--c-text-dim);
  opacity: 0.6;
}

.mission-name {
  color: var(--c-cyan);
  font-size: 0.8rem;
  font-weight: bold;
}

.mission-desc {
  color: var(--c-text-dim);
  font-size: 0.72rem;
  margin-top: 2px;
}
