
.equip-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-title {
  color: var(--c-cyan);
  font-size: 0.75rem;
  font-weight: bold;
  padding: 4px 0;
  border-bottom: 1px solid var(--c-cyan);
  text-shadow: var(--glow-cyan);
}

.equip-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.equip-slot {
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
  cursor: pointer;
  transition: all 0.2s;
}

.equip-slot:hover {
  border-color: var(--c-magenta);
}

.equip-slot.expanded {
  border-color: var(--c-magenta);
  box-shadow: 0 0 8px rgba(255, 0, 255, 0.2);
}

.equip-slot.empty {
  opacity: 0.6;
}

.slot-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  background: rgba(255, 0, 255, 0.05);
  border-bottom: 1px solid var(--c-border);
}

.slot-icon {
  font-size: 1rem;
}

.slot-name {
  color: var(--c-magenta);
  font-size: 0.75rem;
  font-weight: bold;
  text-transform: uppercase;
}

.expand-icon {
  margin-left: auto;
  color: var(--c-text-dim);
  font-size: 0.7rem;
}

.slot-content {
  padding: 8px 10px;
}

.slot-content.empty .gear-name {
  color: var(--c-text-muted);
  font-style: italic;
}

.gear-name {
  color: var(--c-text);
  font-size: 0.85rem;
  font-weight: bold;
}

.slot-detail {
  padding: 8px 10px;
  padding-top: 0;
  border-top: 1px dashed var(--c-border);
  margin-top: 0;
  animation: slideDown 0.2s ease;
}

.detail-label {
  color: var(--c-green);
  font-size: 0.7rem;
  display: block;
  margin-bottom: 4px;
}

.detail-text {
  color: var(--c-text-dim);
  font-size: 0.78rem;
  display: block;
}

@keyframes slideDown {
  from {
    opacity: 0;
    max-height: 0;
  }
  to {
    opacity: 1;
    max-height: 100px;
  }
}
