
.inv-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-title {
  color: var(--c-cyan);
  font-size: 0.75rem;
  font-weight: bold;
  padding: 4px 0;
  border-bottom: 1px solid var(--c-cyan);
  text-shadow: var(--glow-cyan);
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-card {
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
  cursor: pointer;
  transition: all 0.2s;
}

.item-card:hover {
  border-color: var(--c-cyan);
  box-shadow: 0 0 5px rgba(0, 240, 255, 0.2);
}

.item-card.expanded {
  border-color: var(--c-cyan);
}

.item-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
}

.item-icon {
  width: 26px;
  height: 26px;
  background: var(--c-bg-panel);
  border: 1px solid var(--c-cyan);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.65rem;
  font-weight: bold;
  color: var(--c-cyan);
}

.item-name {
  flex: 1;
  color: var(--c-text);
  font-size: 0.85rem;
  font-weight: bold;
}

.item-qty {
  color: var(--c-yellow);
  font-size: 0.75rem;
  font-weight: bold;
  padding: 2px 6px;
  background: rgba(240, 255, 0, 0.1);
  border: 1px solid var(--c-yellow);
}

.expand-icon {
  color: var(--c-text-dim);
  font-size: 0.7rem;
}

.item-detail {
  padding: 8px 10px;
  padding-top: 0;
  color: var(--c-text-dim);
  font-size: 0.78rem;
  border-top: 1px dashed var(--c-border);
  margin-top: 0;
  animation: slideDown 0.2s ease;
}

.detail-prefix {
  color: var(--c-green);
  margin-right: 4px;
}

@keyframes slideDown {
  from {
    opacity: 0;
    max-height: 0;
  }
  to {
    opacity: 1;
    max-height: 100px;
  }
}

.empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 20px;
  color: var(--c-text-dim);
  font-size: 0.85rem;
  background: var(--c-bg-dark);
  border: 1px dashed var(--c-border);
}

.empty-icon {
  color: var(--c-yellow);
  animation: neonPulse 1.5s ease-in-out infinite;
}
