
.cyber-card {
  width: 100%;
  max-width: 720px;
  background: var(--c-bg-panel);
  border: 1px solid var(--c-cyan);
  box-shadow:
    var(--glow-cyan),
    inset 0 0 30px rgba(0, 240, 255, 0.03);
  display: flex;
  flex-direction: column;
  font-family: var(--font-cyber);
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.4;
  margin: 0 auto;
  position: relative;
  overflow: hidden;
}

.scanline {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(to bottom, transparent, rgba(0, 240, 255, 0.15), transparent);
  animation: scanline 4s linear infinite;
  pointer-events: none;
  z-index: 10;
}

.content-area {
  padding: 12px;
  min-height: 0;
  background: var(--c-bg-card);
}

.tab-pane {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-pane.active {
  display: block;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
