
.npc-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-title {
  color: var(--c-cyan);
  font-size: 0.75rem;
  font-weight: bold;
  padding: 4px 0;
  border-bottom: 1px solid var(--c-cyan);
  text-shadow: var(--glow-cyan);
}

.npc-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.npc-card {
  background: var(--c-bg-dark);
  border: 1px solid var(--c-border);
  cursor: pointer;
  transition: all 0.2s;
}

.npc-card:hover {
  border-color: var(--c-yellow);
}

.npc-card.expanded {
  border-color: var(--c-yellow);
  box-shadow: 0 0 8px rgba(240, 255, 0, 0.15);
}

.npc-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
}

.npc-avatar {
  width: 32px;
  height: 32px;
  background: var(--c-bg-panel);
  border: 1px solid var(--c-yellow);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  color: var(--c-yellow);
  font-size: 0.9rem;
}

.npc-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.npc-name {
  color: var(--c-text);
  font-weight: bold;
  font-size: 0.9rem;
}

.npc-role {
  color: var(--c-text-dim);
  font-size: 0.72rem;
}

.attitude-badge {
  padding: 3px 8px;
  font-size: 0.7rem;
  font-weight: bold;
  border: 1px solid;
}

.attitude-badge.positive {
  color: var(--c-green);
  border-color: var(--c-green);
  background: rgba(0, 255, 136, 0.1);
}

.attitude-badge.negative {
  color: var(--c-red);
  border-color: var(--c-red);
  background: rgba(255, 51, 102, 0.1);
}

.attitude-badge.neutral {
  color: var(--c-text-dim);
  border-color: var(--c-border);
  background: rgba(125, 133, 144, 0.1);
}

.attitude-badge.unknown {
  color: var(--c-yellow);
  border-color: var(--c-yellow);
  background: rgba(240, 255, 0, 0.1);
}

.npc-detail {
  padding: 10px;
  padding-top: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  animation: slideDown 0.2s ease;
}

.thought-bubble {
  padding: 8px;
  background: rgba(255, 0, 255, 0.05);
  border-left: 2px solid var(--c-magenta);
}

.thought-prefix {
  color: var(--c-magenta);
  font-size: 0.7rem;
  display: block;
  margin-bottom: 4px;
}

.thought-text {
  color: var(--c-text-dim);
  font-size: 0.8rem;
  font-style: italic;
}

.status-line {
  display: flex;
  gap: 6px;
  font-size: 0.78rem;
}

.status-prefix {
  color: var(--c-cyan);
}

.status-text {
  color: var(--c-text-dim);
}

@keyframes slideDown {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 20px;
  color: var(--c-text-dim);
  font-size: 0.85rem;
  background: var(--c-bg-dark);
  border: 1px dashed var(--c-border);
}

.empty-icon {
  color: var(--c-yellow);
}
